import{_ as r,a0 as d,w as b,s,I as e,x as a,a1 as n,A as l,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const G=JSON.parse('{"title":"如何在 Ubuntu/Fedora/Debian 中安装 GitLab | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu/Fedora/Debian 中安装 GitLab | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu/Fedora/Debian 中安装 GitLab | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu/Fedora/Debian 中安装 GitLab | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151109 How to Install GitLab on Ubuntu or Fedora or Debian","title":"如何在 Ubuntu/Fedora/Debian 中安装 GitLab","tag":"201601","desc":""},"relativePath":"201601/20151109 How to Install GitLab on Ubuntu or Fedora or Debian.md","filePath":"[post].md"}'),p={name:"201601/20151109 How to Install GitLab on Ubuntu or Fedora or Debian.md"};function u(g,t,m,f,h,x){const i=d("Link");return b(),s("div",null,[t[33]||(t[33]=e("h1",{id:"如何在-ubuntu-fedora-debian-中安装-gitlab",tabindex:"-1"},[a("如何在 Ubuntu/Fedora/Debian 中安装 GitLab "),e("a",{class:"header-anchor",href:"#如何在-ubuntu-fedora-debian-中安装-gitlab","aria-label":"Permalink to “如何在 Ubuntu/Fedora/Debian 中安装 GitLab”"},"​")],-1)),e("p",null,[t[1]||(t[1]=a("在 Git 问世之前，分布式版本控制从来都不是一件简单的事。Git 是一个自由开源的软件，旨在轻松且快速地对从小规模到非常巨大的项目进行管理。Git 最开始由 Linus Torvalds 开发，他同时也是著名的 Linux 内核的创建者。在 git 和分布式版本控制系统领域中，",-1)),n(i,{href:"https://about.gitlab.com/"},{default:l(()=>[...t[0]||(t[0]=[a("GitLab",-1)])]),_:1}),t[2]||(t[2]=a(" 是一个极棒的新产品。它是一个基于 web 的 Git 仓库管理应用，包含代码审查、wiki、问题跟踪等诸多功能。使用 GitLab 可以很方便、快速地创建、审查、部署及托管代码。尽管它在其官方的服务器提供了与 Github 类似的免费托管的代码仓库，但它也可以运行在我们自己的服务器上。GitLab 有两个不同的版本：社区版(Community Edition)和企业版(Enterprise Edition)。社区版本完全免费且开源，遵循 MIT 协议；而企业版则遵循一个专有的协议，包含一些社区版中没有的功能。下面介绍的是有关如何在我们自己的运行着 Ubuntu、Fedora 或 Debian 操作系统的机器上安装 GitLab 社区版的简单步骤。",-1))]),t[34]||(t[34]=o(`<h3 id="_1-安装先决条件" tabindex="-1">1. 安装先决条件 <a class="header-anchor" href="#_1-安装先决条件" aria-label="Permalink to “1. 安装先决条件”">​</a></h3><p>首先，我们需要安装 GitLab 所依赖的软件包。我们将安装 <code>curl</code>，用以下载我们所需的文件；安装<code>openssh-server</code> ，以此来通过 ssh 协议登录到我们的机器上；安装<code>ca-certificates</code>，用它来添加 CA 认证；以及 <code>postfix</code>，把它作为一个 MTA(Mail Transfer Agent，邮件传输代理)。</p><p>注： 若要安装 GitLab 社区版，我们需要一个至少包含 2 GB 内存和 2 核 CPU 的 linux 机器。</p><h4 id="在-ubuntu-14-04-debian-8-x-中" tabindex="-1">在 Ubuntu 14 .04/Debian 8.x 中 <a class="header-anchor" href="#在-ubuntu-14-04-debian-8-x-中" aria-label="Permalink to “在 Ubuntu 14 .04/Debian 8.x 中”">​</a></h4><p>鉴于这些依赖包都可以在 Ubuntu 14.04 和 Debian 8.x 的官方软件仓库中获取到，我们只需通过使用 <code>apt-get</code> 包管理器来安装它们。为此，我们需要在一个终端或控制台中执行下面的命令：</p><pre><code># apt-get install curl openssh-server ca-certificates postfix
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/install-dependencies-gitlab-ubuntu-debian.png" alt="install dependencies gitlab ubuntu debian"></p><h4 id="在-fedora-22-中" tabindex="-1">在 Fedora 22 中 <a class="header-anchor" href="#在-fedora-22-中" aria-label="Permalink to “在 Fedora 22 中”">​</a></h4><p>在 Fedora 22 中，由于 <code>yum</code> 已经被弃用了，默认的包管理器是 <code>dnf</code>。为了安装上面那些需要的软件包，我们只需运行下面的 dnf 命令：</p><pre><code># dnf install curl openssh-server postfix
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/install-dependencies-gitlab-fedora.png" alt="install dependencies gitlab fedora"></p><h3 id="_2-打开并开启服务" tabindex="-1">2. 打开并开启服务 <a class="header-anchor" href="#_2-打开并开启服务" aria-label="Permalink to “2. 打开并开启服务”">​</a></h3><p>现在，我们将使用我们默认的初始化系统来打开 sshd 和 postfix 服务。并且我们将使得它们在每次系统启动时被自动开启。</p><h4 id="在-ubuntu-14-04-中" tabindex="-1">在 Ubuntu 14.04 中 <a class="header-anchor" href="#在-ubuntu-14-04-中" aria-label="Permalink to “在 Ubuntu 14.04 中”">​</a></h4><p>由于在 Ubuntu 14.04 中安装的是 SysVinit 初始化系统，我们将使用 service 命令来开启 sshd 和 postfix 守护进程：</p><pre><code># service sshd start
# service postfix start
</code></pre><p>现在，为了使得它们在每次开机启动时被自动开启，我们需要运行下面的 update-rc.d 命令：</p><pre><code># update-rc.d sshd enable
# update-rc.d postfix enable
</code></pre><h4 id="在-fedora-22-debian-8-x-中" tabindex="-1">在 Fedora 22/Debian 8.x 中 <a class="header-anchor" href="#在-fedora-22-debian-8-x-中" aria-label="Permalink to “在 Fedora 22/Debian 8.x 中”">​</a></h4><p>鉴于 Fedora 22 和 Debian 8.x 已经用 Systemd 代替了 SysVinit 来作为默认的初始化系统，我们只需运行下面的命令来开启 sshd 和 postfix 服务：</p><pre><code># systemctl start sshd postfix
</code></pre><p>现在，为了使得它们在每次开机启动时可以自动运行，我们需要运行下面的 systemctl 命令：</p><pre><code># systemctl enable sshd postfix

Created symlink from /etc/systemd/system/multi-user.target.wants/sshd.service to /usr/lib/systemd/system/sshd.service.
Created symlink from /etc/systemd/system/multi-user.target.wants/postfix.service to /usr/lib/systemd/system/postfix.service.
</code></pre><h3 id="_3-下载-gitlab" tabindex="-1">3. 下载 GitLab <a class="header-anchor" href="#_3-下载-gitlab" aria-label="Permalink to “3. 下载 GitLab”">​</a></h3><p>现在，我们将使用 curl 从官方的 GitLab 社区版仓库下载二进制安装文件。首先，为了得到所需文件的下载链接，我们需要浏览到该软件仓库的页面。为此，我们需要在运行着相应操作系统的 linux 机器上运行下面的命令。</p><h4 id="在-ubuntu-14-04-中-1" tabindex="-1">在 Ubuntu 14.04 中 <a class="header-anchor" href="#在-ubuntu-14-04-中-1" aria-label="Permalink to “在 Ubuntu 14.04 中”">​</a></h4>`,26)),e("p",null,[t[4]||(t[4]=a("由于 Ubuntu 和 Debian 使用相同的 debian 格式的安装包，我们需要在 ",-1)),n(i,{href:"https://packages.gitlab.com/gitlab/gitlab-ce?filter=debs"},{default:l(()=>[...t[3]||(t[3]=[a("https://packages.gitlab.com/gitlab/gitlab-ce?filter=debs",-1)])]),_:1}),t[5]||(t[5]=a(" 下搜索所需版本的 GitLab，然后点击有着 ubuntu/trusty 标签的链接，即我们运行着的 Ubuntu 14.04。接着一个新的页面将会出现，我们将看到一个下载按钮，然后我们在它的上面右击，得到文件的链接，然后像下面这样使用 curl 来下载它。",-1))]),t[35]||(t[35]=e("pre",null,[e("code",null,`# curl https://packages.gitlab.com/gitlab/gitlab-ce/packages/ubuntu/trusty/gitlab-ce_8.1.2-ce.0_amd64.deb
`)],-1)),t[36]||(t[36]=e("p",null,[e("img",{src:"http://blog.linoxide.com/wp-content/uploads/2015/10/downloading-gitlab-ubuntu.png",alt:"Downloading Gitlab Ubuntu"})],-1)),t[37]||(t[37]=e("h4",{id:"在-debian-8-x-中",tabindex:"-1"},[a("在 Debian 8.x 中 "),e("a",{class:"header-anchor",href:"#在-debian-8-x-中","aria-label":"Permalink to “在 Debian 8.x 中”"},"​")],-1)),e("p",null,[t[7]||(t[7]=a("与 Ubuntu 类似，我们需要在 ",-1)),n(i,{href:"https://packages.gitlab.com/gitlab/gitlab-ce?filter=debs"},{default:l(()=>[...t[6]||(t[6]=[a("https://packages.gitlab.com/gitlab/gitlab-ce?filter=debs",-1)])]),_:1}),t[8]||(t[8]=a(" 页面中搜索所需版本的 GitLab，然后点击带有 debian/jessie 标签的链接，即我们运行着的 Debian 8.x。接着，一个新的页面将会出现，然后我们在下载按钮上右击，得到文件的下载链接。最后我们像下面这样使用 curl 来下载该文件。",-1))]),t[38]||(t[38]=e("pre",null,[e("code",null,`# curl https://packages.gitlab.com/gitlab/gitlab-ce/packages/debian/jessie/gitlab-ce_8.1.2-ce.0_amd64.deb/download
`)],-1)),t[39]||(t[39]=e("p",null,[e("img",{src:"http://blog.linoxide.com/wp-content/uploads/2015/10/downloading-gitlab-debian.png",alt:"Downloading Gitlab Debian"})],-1)),t[40]||(t[40]=e("h4",{id:"在-fedora-22-中-1",tabindex:"-1"},[a("在 Fedora 22 中#### "),e("a",{class:"header-anchor",href:"#在-fedora-22-中-1","aria-label":"Permalink to “在 Fedora 22 中####”"},"​")],-1)),e("p",null,[t[10]||(t[10]=a("由于 Fedora 使用 rpm 文件来作为软件包，我们将在 ",-1)),n(i,{href:"https://packages.gitlab.com/gitlab/gitlab-ce?filter=rpms"},{default:l(()=>[...t[9]||(t[9]=[a("https://packages.gitlab.com/gitlab/gitlab-ce?filter=rpms",-1)])]),_:1}),t[11]||(t[11]=a(" 页面下搜索所需版本的 GitLab，然后点击所需发行包的链接，这里由于我们运行的是 Fedora 22，所以我们将选择带有 el/7 标签的发行包。一个新的页面将会出现，在其中我们可以看到一个下载按钮，我们将右击它，得到所需文件的链接，然后像下面这样使用 curl 来下载它。",-1))]),t[41]||(t[41]=o(`<pre><code># curl https://packages.gitlab.com/gitlab/gitlab-ce/packages/el/7/gitlab-ce-8.1.2-ce.0.el7.x86_64.rpm/download
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/downloading-gitlab-fedora.png" alt="Downloading Gitlab Fedora"></p><h3 id="_4-安装-gitlab" tabindex="-1">4. 安装 GitLab <a class="header-anchor" href="#_4-安装-gitlab" aria-label="Permalink to “4. 安装 GitLab”">​</a></h3><p>在相应的软件源被添加到我们的 linux 机器上之后，现在我们将使用相应 linux 发行版本中的默认包管理器来安装 GitLab 社区版。</p><h4 id="在-ubuntu-14-04-debian-8-x-中-1" tabindex="-1">在 Ubuntu 14.04/Debian 8.x 中 <a class="header-anchor" href="#在-ubuntu-14-04-debian-8-x-中-1" aria-label="Permalink to “在 Ubuntu 14.04/Debian 8.x 中”">​</a></h4><p>要在运行着 Ubuntu 14.04 或 Debian 8.x linux 发行版本的机器上安装 GitLab 社区版，我们只需运行如下的命令：</p><pre><code># dpkg -i gitlab-ce_8.1.2-ce.0_amd64.deb
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/installing-gitlab-ubuntu-debian.png" alt="Installing Gitlab Ubuntu Debian"></p><h4 id="在-fedora-22-中-2" tabindex="-1">在 Fedora 22 中 <a class="header-anchor" href="#在-fedora-22-中-2" aria-label="Permalink to “在 Fedora 22 中”">​</a></h4><p>我们只需执行下面的 dnf 命令来在我们的 Fedora 22 机器上安装 GitLab。</p><pre><code># dnf install gitlab-ce-8.1.2-ce.0.el7.x86_64.rpm
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/installing-gitlab-fedora.png" alt="Installing Gitlab Fedora"></p><h3 id="_5-配置和开启-gitlab" tabindex="-1">5. 配置和开启 GitLab <a class="header-anchor" href="#_5-配置和开启-gitlab" aria-label="Permalink to “5. 配置和开启 GitLab”">​</a></h3><p>GitLab 社区版已经成功地安装在我们的 linux 系统中了，接下来我们将要配置和开启它了。为此，我们需要运行下面的命令，这在 Ubuntu、Debian 和 Fedora 发行版本上都一样：</p><pre><code># gitlab-ctl reconfigure
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/reconfiguring-gitlab.png" alt="Reconfiguring Gitlab"></p><h3 id="_6-允许通过防火墙" tabindex="-1">6. 允许通过防火墙 <a class="header-anchor" href="#_6-允许通过防火墙" aria-label="Permalink to “6. 允许通过防火墙”">​</a></h3><p>假如在我们的 linux 机器中已经启用了防火墙程序，为了使得 GitLab 社区版的 web 界面可以通过网络进行访问，我们需要允许 80 端口通过防火墙，这个端口是 GitLab 社区版的默认端口。为此，我们需要运行下面的命令。</p><h4 id="在-iptables-中" tabindex="-1">在 iptables 中 <a class="header-anchor" href="#在-iptables-中" aria-label="Permalink to “在 iptables 中”">​</a></h4><p>Ubuntu 14.04 默认安装和使用的是 iptables。所以，我们将运行下面的 iptables 命令来打开 80 端口：</p><pre><code># iptables -A INPUT -p tcp -m tcp --dport 80 -j ACCEPT

# /etc/init.d/iptables save
</code></pre><h4 id="在-firewalld-中" tabindex="-1">在 firewalld 中 <a class="header-anchor" href="#在-firewalld-中" aria-label="Permalink to “在 firewalld 中”">​</a></h4><p>由于 Fedora 22 和 Debian 8.x 默认安装了 systemd，它包含了作为防火墙程序的 firewalld。为了使得 80 端口（http 服务） 能够通过 firewalld，我们需要执行下面的命令。</p><pre><code># firewall-cmd --permanent --add-service=http

success

# firewall-cmd --reload

success
</code></pre><h3 id="_7-访问-gitlab-web-界面" tabindex="-1">7. 访问 GitLab Web 界面 <a class="header-anchor" href="#_7-访问-gitlab-web-界面" aria-label="Permalink to “7. 访问 GitLab Web 界面”">​</a></h3>`,25)),e("p",null,[t[14]||(t[14]=a("最后，我们将访问 GitLab 社区版的 web 界面。为此，我们需要将我们的 web 浏览器指向 GitLab 服务器的网址，根据我们的配置，可能是 ",-1)),n(i,{href:"http://ip-address/"},{default:l(()=>[...t[12]||(t[12]=[a("http://ip-address/",-1)])]),_:1}),t[15]||(t[15]=a(" 或 ",-1)),n(i,{href:"http://domain.com/"},{default:l(()=>[...t[13]||(t[13]=[a("http://domain.com/",-1)])]),_:1}),t[16]||(t[16]=a(" 的格式。在我们成功指向该网址后，我们将会看到下面的页面。",-1))]),t[42]||(t[42]=o('<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/gitlab-login-screen.png" alt="Gitlab Login Screen"></p><p>现在，为了登录进面板，我们需要点击登录按钮，它将询问我们的用户名和密码。然后我们将输入默认的用户名和密码，即 <strong>root</strong> 和 <strong>5iveL!fe</strong> 。在登录进控制面板后，我们将被强制要求为我们的 GitLab root 用户输入新的密码。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/setting-new-password-gitlab.png" alt="Setting New Password Gitlab"></p><h3 id="_8-创建仓库" tabindex="-1">8. 创建仓库 <a class="header-anchor" href="#_8-创建仓库" aria-label="Permalink to “8. 创建仓库”">​</a></h3><p>在我们成功地更改密码并登录到我们的控制面板之后，现在，我们将为我们的新项目创建一个新的仓库。为此，我们需要来到项目栏，然后点击 <strong>新项目</strong> 绿色按钮。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/creating-new-projects.png" alt="Creating New Projects"></p><p>接着，我们将被询问给我们的项目输入所需的信息和设定，正如下面展示的那样。我们甚至可以从其他的 git 仓库提供商和仓库中导入我们的项目。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/configuring-git-project.png" alt="Creating New Project"></p><p>做完这些后，我们将能够使用任何包含基本 git 命令行的 Git 客户端来访问我们的 Git 仓库。我们可以看到在仓库中进行的任何活动，例如创建一个里程碑，管理问题，合并请求，管理成员，便签，Wiki 等。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/gitlab-menu.png" alt="Gitlab Menu"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3>',11)),e("p",null,[t[18]||(t[18]=a("GitLab 是一个用来管理 git 仓库的很棒的开源 web 应用。它有着漂亮的带有诸多酷炫功能的响应式界面。它还打包有许多酷炫功能，例如管理群组，分发密钥，持续集成，查看日志，广播消息，钩子，系统 OAuth 应用，模板等。（注：OAuth 是一个开放标准，允许用户让第三方应用访问该用户在某一网站上存储的私密的资源（如照片，视频，联系人列表），而无需将用户名和密码提供给第三方应用。--- 摘取自 ",-1)),n(i,{href:"https://zh.wikipedia.org/wiki/OAuth"},{default:l(()=>[...t[17]||(t[17]=[a("维基百科上的 OAuth 词条",-1)])]),_:1}),t[19]||(t[19]=a("） 它还可以和大量的工具进行交互如 Slack，Hipchat，LDAP，JIRA，Jenkins，有很多类型的钩子和完整的 API。它至少需要 2 GB 的内存和 2 核 CPU 来流畅运行，支持多达 500 个用户，但它也可以被扩展到多个工作服务器上。",-1))]),t[43]||(t[43]=e("p",null,"假如你有任何的问题，建议，回馈，请将它们写在下面的评论框中，以便我们可以提升或更新我们的内容。谢谢！",-1)),t[44]||(t[44]=e("hr",null,null,-1)),e("p",null,[t[21]||(t[21]=a("via: ",-1)),n(i,{href:"http://linoxide.com/linux-how-to/install-gitlab-on-ubuntu-fedora-debian/"},{default:l(()=>[...t[20]||(t[20]=[a("http://linoxide.com/linux-how-to/install-gitlab-on-ubuntu-fedora-debian/",-1)])]),_:1})]),e("p",null,[t[25]||(t[25]=a("作者：",-1)),n(i,{href:"http://linoxide.com/author/arunp/"},{default:l(()=>[...t[22]||(t[22]=[a("Arun Pyasi",-1)])]),_:1}),t[26]||(t[26]=a(" 译者：",-1)),n(i,{href:"https://github.com/FSSlc"},{default:l(()=>[...t[23]||(t[23]=[a("FSSlc",-1)])]),_:1}),t[27]||(t[27]=a(" 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[24]||(t[24]=[a("wxy",-1)])]),_:1})]),e("p",null,[t[30]||(t[30]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[28]||(t[28]=[a("LCTT",-1)])]),_:1}),t[31]||(t[31]=a(" 原创编译，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...t[29]||(t[29]=[a("Linux中国",-1)])]),_:1}),t[32]||(t[32]=a(" 荣誉推出",-1))])])}const L=r(p,[["render",u]]);export{G as __pageData,L as default};
